const KB = [{"id":"glossary-apex","title":"Apex","category":"Glossary","text":"Apex. The apex is the innermost point of a corner, the spot the racing line clips. Hitting the apex well sets up a fast exit onto the next straight."},{"id":"glossary-backmarker","title":"Backmarker","category":"Glossary","text":"Backmarker. A backmarker is a slower car running near the back of the field, often about to be lapped by the leaders. Leaders get blue flags to tell backmarkers to move aside."},{"id":"glossary-blistering","title":"Blistering","category":"Glossary","text":"Blistering. Blistering is when a tyre overheats and bubbles form on its surface, which causes a sudden loss of grip. It is different from graining, which is caused by sliding rather than excess heat."},{"id":"glossary-box-box-pit-call","title":"Box, Box (pit call)","category":"Glossary","text":"Box, Box (pit call). \"Box, box\" is the radio call telling a driver to come into the pits on this lap. \"Box\" just means the pit garage area. A call like \"stay out\" means the driver should not pit yet."},{"id":"glossary-brake-bias","title":"Brake bias","category":"Glossary","text":"Brake bias. Brake bias is how braking force is split between the front and rear wheels. Drivers adjust it from the steering wheel during the race as fuel burns off, tyres wear, and corners change."},{"id":"glossary-chicane","title":"Chicane","category":"Glossary","text":"Chicane. A chicane is a quick sequence of two or three tight corners in alternating directions, usually put in to slow cars down before a fast section."},{"id":"glossary-classified-in-the-results","title":"Classified (in the results)","category":"Glossary","text":"Classified (in the results). A driver is classified in the race result if they complete at least 90 percent of the winner's race distance, even if they did not finish on track because of a crash or failure. Unclassified cars appear below the finishers."},{"id":"glossary-clean-air","title":"Clean air","category":"Glossary","text":"Clean air. Clean air means a car has nothing directly ahead of it, so the air hitting its wings is smooth and the car performs at its best. The opposite is dirty air."},{"id":"glossary-compound","title":"Compound","category":"Glossary","text":"Compound. A compound is the type of rubber mix in a tyre. Softer compounds give more grip but wear out faster, harder compounds last longer but are slower. See the tyres section for the colours."},{"id":"glossary-constructors-championship","title":"Constructors' Championship","category":"Glossary","text":"Constructors' Championship. The Constructors' Championship is the team title. Every point scored by a team's two drivers is added together, and the team with the most points at the end of the season wins it."},{"id":"glossary-cost-cap","title":"Cost cap","category":"Glossary","text":"Cost cap. The cost cap is a limit on how much money a team can spend on developing and running its car in a season. It exists to stop the richest teams from buying a permanent advantage. Some items, such as driver salaries, sit outside the cap. Breaking the cap is punished with fines and other sporting penalties."},{"id":"glossary-degradation-deg","title":"Degradation (deg)","category":"Glossary","text":"Degradation (deg). Tyre degradation, usually just called deg, is the gradual loss of grip and lap time as a tyre wears out. Commentators say \"high deg\" when tyres are wearing quickly."},{"id":"glossary-delta","title":"Delta","category":"Glossary","text":"Delta. Delta is a time difference between two laps or two cars. A negative delta means faster, positive means slower. Under a Virtual Safety Car, drivers must stay above a target delta shown on their steering wheel."},{"id":"glossary-dnf-dns-dsq","title":"DNF, DNS, DSQ","category":"Glossary","text":"DNF, DNS, DSQ. DNF means did not finish, DNS means did not start, and DSQ means disqualified. DSQ is usually a technical rule breach found in checks after the race, or a black flag during it."},{"id":"glossary-downforce","title":"Downforce","category":"Glossary","text":"Downforce. Downforce is the aerodynamic force that presses the car into the track, so it can corner much faster. More downforce means more cornering grip but also more drag, which lowers straight-line speed."},{"id":"glossary-drag","title":"Drag","category":"Glossary","text":"Drag. Drag is air resistance that slows the car, especially on straights. Teams balance downforce for the corners against low drag for the straights."},{"id":"glossary-drs-drag-reduction-system-retired","title":"DRS (Drag Reduction System, retired)","category":"Glossary","text":"DRS (Drag Reduction System, retired). DRS was a flap on the rear wing that a chasing driver could open within one second of the car ahead to cut drag and get a speed boost. It ran from 2011 to 2025. It no longer exists in 2026: it has been replaced by active aerodynamics (Straight Mode and Corner Mode) and by Overtake Mode, which is a battery-power boost rather than a wing flap. Older articles, videos and games still mention DRS."},{"id":"glossary-drivers-championship","title":"Drivers' Championship","category":"Glossary","text":"Drivers' Championship. The Drivers' Championship is the individual title. The driver with the most points over the season wins it."},{"id":"glossary-energy-deployment-and-harvesting-2026","title":"Energy deployment and harvesting (2026)","category":"Glossary","text":"Energy deployment and harvesting (2026). In the 2026 cars, drivers and engineers constantly manage the battery. Deployment means using stored electrical energy to add power. Harvesting (or recharging) means putting energy back into the battery, for example under braking. A car with a lot of energy left can attack or defend with more power."},{"id":"glossary-ers-energy-recovery-system","title":"ERS (Energy Recovery System)","category":"Glossary","text":"ERS (Energy Recovery System). ERS is the hybrid part of an F1 power unit. It recovers energy that would be wasted, stores it in a battery, and gives it back as extra electrical power to the car. In 2026 the electrical side of the power unit is much bigger than before."},{"id":"glossary-fia","title":"FIA","category":"Glossary","text":"FIA. The FIA, the Fédération Internationale de l'Automobile, is the governing body that writes and enforces the rules of Formula 1. Formula One Management (FOM) handles the commercial side, including TV rights."},{"id":"glossary-fastest-lap","title":"Fastest lap","category":"Glossary","text":"Fastest lap. The fastest lap is the quickest single lap of the race. Since 2025 it no longer earns a championship point, though it is still shown in purple on the timing screens and counted as a stat."},{"id":"glossary-formation-lap","title":"Formation lap","category":"Glossary","text":"Formation lap. The formation lap is the lap before the race start, when cars leave the pit lane, drive round to the grid, and warm up tyres and brakes by weaving and braking. No overtaking is allowed. The cars then take their grid slots for the start."},{"id":"glossary-front-row","title":"Front row","category":"Glossary","text":"Front row. The front row is the first two starting grid positions: pole position and second place, side by side. Starting on the front row is a big advantage because there is no one ahead for the first corner."},{"id":"glossary-gap-and-interval","title":"Gap and interval","category":"Glossary","text":"Gap and interval. The gap is the time difference to the race leader, and the interval is the time difference to the car directly ahead. TV graphics show both next to each driver. In 2026 an interval below one second at the detection point matters for Overtake Mode."},{"id":"glossary-graining","title":"Graining","category":"Glossary","text":"Graining. Graining is when small bits of rubber tear off the tyre surface because it is sliding, leaving a rough, grippy-looking but slower surface. It tends to fade away after some laps."},{"id":"glossary-grid-and-grid-slot","title":"Grid and grid slot","category":"Glossary","text":"Grid and grid slot. The grid is the starting formation, two cars per row, set by qualifying. A grid slot is the position a car starts from. Pole is slot one."},{"id":"glossary-grid-penalty","title":"Grid penalty","category":"Glossary","text":"Grid penalty. A grid penalty moves a car back a number of places from where it qualified, usually for changing too many power unit parts or a technical or driving breach. It is applied before the race starts."},{"id":"glossary-halo","title":"Halo","category":"Glossary","text":"Halo. The halo is the curved titanium bar above the cockpit that protects the driver's head from large debris and impacts. It has been mandatory since 2018."},{"id":"glossary-hairpin","title":"Hairpin","category":"Glossary","text":"Hairpin. A hairpin is a very tight corner, close to a 180-degree turn, taken at low speed. They are often good overtaking spots."},{"id":"glossary-in-lap-and-out-lap","title":"In-lap and out-lap","category":"Glossary","text":"In-lap and out-lap. An in-lap is the lap on which a driver drives into the pits. An out-lap is the lap on which they leave the pits. Teams often talk about being quick on the out-lap on fresh tyres, because that matters for the undercut."},{"id":"glossary-kerb","title":"Kerb","category":"Glossary","text":"Kerb. A kerb (curb in the US) is the raised painted strip at the edge of the track at a corner. Drivers use it to take a faster line, but hitting the wrong one can unsettle or damage the car."},{"id":"glossary-lap-record","title":"Lap record","category":"Glossary","text":"Lap record. The lap record is the fastest lap ever set in a race at that circuit. A related term, track record, can include qualifying laps."},{"id":"glossary-lapped-car","title":"Lapped car","category":"Glossary","text":"Lapped car. A car is lapped when the race leader catches and passes it, putting it one full lap behind. Lapped cars are shown the blue flag so they let the leaders through."},{"id":"glossary-lift-and-coast","title":"Lift and coast","category":"Glossary","text":"Lift and coast. Lift and coast means a driver lifts off the throttle before the braking zone and rolls into the corner to save fuel, protect tyres or brakes, or harvest battery energy. In 2026 it is a normal part of energy management, so you may hear engineers ask drivers to do it."},{"id":"glossary-lights-out","title":"Lights out","category":"Glossary","text":"Lights out. Lights out is the moment at the start when the five red lights above the grid go out and the race begins. Every car must stay still until then."},{"id":"glossary-lock-up","title":"Lock-up","category":"Glossary","text":"Lock-up. A lock-up is when a driver brakes so hard that a tyre stops rotating and slides, producing a puff of smoke and often a flat spot on the tyre that causes vibrations."},{"id":"glossary-manage-as-in-manage-the-pace","title":"Manage (as in \"manage the pace\")","category":"Glossary","text":"Manage (as in \"manage the pace\"). When an engineer tells a driver to manage, it means to not push flat out and to protect tyres, brakes, fuel or battery energy, usually because the gap to the next car is comfortable. The opposite is \"push\"."},{"id":"glossary-marbles","title":"Marbles","category":"Glossary","text":"Marbles. Marbles are small pieces of rubber thrown off tyres that collect off the racing line. Driving through them is very slippery, which is why overtaking wide can be risky."},{"id":"glossary-marshals","title":"Marshals","category":"Glossary","text":"Marshals. Marshals are the volunteers around the circuit who wave flags, clear debris and help with recoveries. Many are trained and are real heroes of the sport."},{"id":"glossary-mgu-k-and-mgu-h","title":"MGU-K and MGU-H","category":"Glossary","text":"MGU-K and MGU-H. The MGU-K (Motor Generator Unit, Kinetic) recovers energy under braking and delivers extra power to the wheels. The MGU-H (Heat) recovered energy from exhaust heat via the turbo; it has been removed in 2026, which made the power unit simpler, and in 2026 the MGU-K is far more powerful."},{"id":"glossary-monocoque","title":"Monocoque","category":"Glossary","text":"Monocoque. The monocoque, or tub, is the strong carbon-fibre survival cell that the driver sits in. The engine, suspension and wings attach to it. It is crash-tested heavily."},{"id":"glossary-oversteer-and-understeer","title":"Oversteer and understeer","category":"Glossary","text":"Oversteer and understeer. Oversteer is when the rear of the car slides out and the car turns more than the driver intended. Understeer is when the front tyres lose grip and the car pushes wide, turning less than intended."},{"id":"glossary-overcut-and-undercut","title":"Overcut and undercut","category":"Glossary","text":"Overcut and undercut. These are pit stop strategies. An undercut means pitting earlier than the car ahead, using fresh tyres to set fast laps, and coming out in front after they stop. An overcut means staying out longer on older tyres, hoping to be quick enough in clean air to get ahead when the rival pits."},{"id":"glossary-paddock","title":"Paddock","category":"Glossary","text":"Paddock. The paddock is the area behind the pit garages where teams have their motorhomes, hospitality and offices. Journalists, drivers and guests gather there."},{"id":"glossary-parc-ferm","title":"Parc fermé","category":"Glossary","text":"Parc fermé. Parc fermé (French for closed park) means the cars are under restricted conditions and the teams cannot freely work on them. Once qualifying begins, teams can only make tightly limited changes, so the setup they choose is close to what they race. See the rules section for details."},{"id":"glossary-pit-lane-pit-box-and-pit-wall","title":"Pit lane, pit box and pit wall","category":"Glossary","text":"Pit lane, pit box and pit wall. The pit lane is the road next to the track where cars stop for service. Each team has a pit box, its own marked bay where mechanics work. The pit wall is the row of control desks where engineers and strategists watch data and run the race."},{"id":"glossary-pit-stop","title":"Pit stop","category":"Glossary","text":"Pit stop. A pit stop is when a car enters the pit lane so the crew can change tyres and make minor adjustments. The wheel change itself takes roughly two seconds for a good crew, and most of the time lost is from driving the pit lane at a limited speed. Refuelling has been banned since 2010."},{"id":"glossary-pole-position","title":"Pole position","category":"Glossary","text":"Pole position. Pole position is first place on the starting grid, given to the driver who sets the fastest lap in qualifying. In the sprint format there are two poles: one for the sprint and one for the grand prix."},{"id":"glossary-podium","title":"Podium","category":"Glossary","text":"Podium. The podium is the platform where the top three finishers receive trophies. A driver finishing in the top three is said to be \"on the podium\"."},{"id":"glossary-power-unit","title":"Power unit","category":"Glossary","text":"Power unit. The power unit is what F1 calls its engine system. It is a 1.6 litre V6 turbo combustion engine plus the hybrid electrical parts. The 2026 version is a big overhaul described in the 2026 cars section."},{"id":"glossary-purple-sector","title":"Purple sector","category":"Glossary","text":"Purple sector. On the timing screens a sector time in purple is the fastest anyone has gone in that sector so far in the session. Green is a driver's own personal best, and yellow is slower than their best."},{"id":"glossary-push","title":"Push","category":"Glossary","text":"Push. Push means drive at maximum pace. \"Push, push, push\" on the radio usually means the team sees an opportunity, such as getting an undercut, or needs the driver to build a gap."},{"id":"glossary-race-director","title":"Race Director","category":"Glossary","text":"Race Director. The Race Director runs the event from race control: starts races, decides on Safety Cars and red flags, and manages the safety of the track. The Race Director is different from the stewards, who judge incidents and give penalties."},{"id":"glossary-reprimand","title":"Reprimand","category":"Glossary","text":"Reprimand. A reprimand is a formal warning from the stewards for a minor breach. It carries no time penalty, but a driver who collects repeated reprimands can face further sanctions."},{"id":"glossary-retirement","title":"Retirement","category":"Glossary","text":"Retirement. A retirement means the driver stopped racing, either because of a crash, mechanical failure, or by team decision. It shows as DNF if they did not complete enough laps to be classified."},{"id":"glossary-sector-and-mini-sector","title":"Sector and mini-sector","category":"Glossary","text":"Sector and mini-sector. Every lap is split into three sectors, each timed separately. Many circuits also have much smaller mini-sectors that power the live colour coded timing bars."},{"id":"glossary-slipstream-tow","title":"Slipstream (tow)","category":"Glossary","text":"Slipstream (tow). Slipstream, also called the tow, is the reduced air resistance a car gets when driving close behind another one on a straight. It lets the following car go faster than it could alone, helping with overtaking."},{"id":"glossary-stewards","title":"Stewards","category":"Glossary","text":"Stewards. The stewards are the officials who investigate incidents and decide on penalties. They watch replays and data and can reach a decision during or after the race. You will see messages like \"under investigation\" on screen."},{"id":"glossary-stint","title":"Stint","category":"Glossary","text":"Stint. A stint is the period a driver spends on track between two pit stops, on one set of tyres."},{"id":"glossary-super-licence","title":"Super licence","category":"Glossary","text":"Super licence. A super licence is the permit every F1 driver needs. Penalty points for driving offences are added to it. Reaching 12 points within 12 months gives a one-race ban."},{"id":"glossary-team-orders","title":"Team orders","category":"Glossary","text":"Team orders. Team orders are instructions from a team to its drivers, such as letting a teammate through or holding position. They are allowed in Formula 1, though some are unpopular with fans."},{"id":"glossary-team-principal","title":"Team principal","category":"Glossary","text":"Team principal. The team principal is the boss of the team, who leads the pit wall and speaks for the team to the media."},{"id":"glossary-traction","title":"Traction","category":"Glossary","text":"Traction. Traction is the grip that lets the car put its power down when accelerating, especially out of slow corners."},{"id":"glossary-tyre-cliff","title":"Tyre cliff","category":"Glossary","text":"Tyre cliff. A tyre cliff is when a worn tyre suddenly loses lots of grip instead of fading slowly, causing lap times to fall away sharply. Teams try to pit before the cliff."},{"id":"glossary-tyre-warmers","title":"Tyre warmers","category":"Glossary","text":"Tyre warmers. Tyre warmers are electric blankets teams wrap around tyres before they are fitted so they work well straight away. They are used in the garage and on the grid, but not during the race."},{"id":"glossary-weaving-on-the-formation-lap","title":"Weaving on the formation lap","category":"Glossary","text":"Weaving on the formation lap. Drivers swerve left and right on the formation lap to put heat into their tyres. It is not a sign that something is wrong."},{"id":"glossary-aquaplaning","title":"Aquaplaning","category":"Glossary","text":"Aquaplaning. Aquaplaning is when a tyre rides on a thin film of standing water instead of gripping the track, so the driver loses steering and braking for a moment. It is a big danger in heavy rain, and it is one reason races get stopped or start behind the Safety Car."},{"id":"glossary-banker-lap","title":"Banker lap","category":"Glossary","text":"Banker lap. A banker lap is a safe, solid lap set early in a qualifying session so a driver is sure to progress to the next round, before taking more risks on later attempts."},{"id":"glossary-common-abbreviations-fp1-q1-sq-gp-sc-vsc","title":"Common abbreviations (FP1, Q1, SQ, GP, SC, VSC)","category":"Glossary","text":"Common abbreviations (FP1, Q1, SQ, GP, SC, VSC). FP1, FP2 and FP3 are the three free practice sessions. Q1, Q2 and Q3 are the qualifying rounds. SQ1 to SQ3 are the Sprint Qualifying rounds. GP is grand prix, SC is Safety Car, VSC is Virtual Safety Car, and P1, P2 and so on mean first position, second position and so on."},{"id":"glossary-cool-down-lap","title":"Cool-down lap","category":"Glossary","text":"Cool-down lap. The cool-down lap is the slow lap after the chequered flag, when drivers return to the pits to park in parc fermé. Cars are often slowed to let the engine and brakes cool, and drivers sometimes wave to fans or pick up flags."},{"id":"glossary-differential","title":"Differential","category":"Glossary","text":"Differential. The differential lets the two driven rear wheels turn at different speeds in a corner. F1 drivers adjust its settings from the steering wheel to change how the car turns in and puts power down."},{"id":"glossary-dive-bomb","title":"Dive-bomb","category":"Glossary","text":"Dive-bomb. A dive-bomb is an aggressive overtake where a driver brakes very late and lunges into a gap from far back. If the car is not properly alongside by the apex, it can end in contact and a penalty."},{"id":"glossary-flat-spot","title":"Flat spot","category":"Glossary","text":"Flat spot. A flat spot is a worn patch on a tyre caused by a lock-up. It makes the car vibrate, and drivers often ask for a stop to change the tyre."},{"id":"glossary-flying-lap-hot-lap-push-lap","title":"Flying lap (hot lap, push lap)","category":"Glossary","text":"Flying lap (hot lap, push lap). A flying lap is a full-speed timed lap, such as in qualifying. A driver gets onto one by first doing a slower preparation lap to warm the tyres and make space."},{"id":"glossary-gearbox","title":"Gearbox","category":"Glossary","text":"Gearbox. F1 cars use a semi-automatic gearbox with eight forward gears, changed by paddles on the steering wheel, and shifts take only a few thousandths of a second. Teams can only use a limited number of gearboxes before facing a penalty."},{"id":"glossary-green-track","title":"Green track","category":"Glossary","text":"Green track. A green track is one with little rubber on the surface, such as at the start of a weekend or after rain, so grip is low and gets better as more cars run."},{"id":"glossary-ground-effect","title":"Ground effect","category":"Glossary","text":"Ground effect. Ground effect is how the shaped underside of the car, the floor, creates downforce by sucking the car towards the track. It was brought back in 2022 and is a main source of downforce on modern F1 cars."},{"id":"glossary-hat-trick-and-grand-slam","title":"Hat-trick and grand slam","category":"Glossary","text":"Hat-trick and grand slam. A hat-trick is when a driver takes pole position, wins the race, and sets the fastest lap in the same weekend. A grand slam is a hat-trick where they also lead every lap of the race."},{"id":"glossary-homologation","title":"Homologation","category":"Glossary","text":"Homologation. Homologation is the official approval of a part, such as a power unit design or a safety structure, as legal and safe. Once approved, changes are tightly restricted."},{"id":"glossary-installation-lap","title":"Installation lap","category":"Glossary","text":"Installation lap. An installation lap is a short outing to check that the car is working properly, such as before qualifying or the race. The driver returns to the pits straight after without setting a competitive time."},{"id":"glossary-lights-to-flag-win","title":"Lights-to-flag win","category":"Glossary","text":"Lights-to-flag win. A lights-to-flag win is when a driver leads from the start lights until the chequered flag without ever losing the lead on track."},{"id":"glossary-pit-limiter","title":"Pit limiter","category":"Glossary","text":"Pit limiter. The pit limiter is a button that holds the car to the pit lane speed limit. Drivers press it as they enter the pit lane and release it at the exit. Speeding in the pit lane is penalised."},{"id":"glossary-pit-window","title":"Pit window","category":"Glossary","text":"Pit window. The pit window is the range of laps in which a pit stop makes sense, based on tyre wear and the gaps to other cars. Teams talk about \"opening the window\" when a stop becomes worthwhile."},{"id":"glossary-porpoising","title":"Porpoising","category":"Glossary","text":"Porpoising. Porpoising is when a car bounces up and down at high speed because the airflow under the floor stalls and recovers repeatedly. It was a big problem when ground effect returned in 2022, and teams had to change setups to reduce it."},{"id":"glossary-race-sim-and-long-run","title":"Race sim and long run","category":"Glossary","text":"Race sim and long run. A race sim or long run is when a team uses practice to run many laps on race-type tyres and fuel, to learn the pace and tyre wear over a full stint. These runs tell you more about race pace than a single fast lap."},{"id":"glossary-racing-line","title":"Racing line","category":"Glossary","text":"Racing line. The racing line is the fastest path round the track, usually wide on entry, close to the apex, and wide on exit. Drivers leave it to defend or pass, but the rubber on that line gives the most grip."},{"id":"glossary-reserve-driver","title":"Reserve driver","category":"Glossary","text":"Reserve driver. A reserve driver is a team's stand-in who can take over if a race driver is ill or injured. They often work in the simulator and help the team in the garage."},{"id":"glossary-scrutineering","title":"Scrutineering","category":"Glossary","text":"Scrutineering. Scrutineering is the FIA's technical checking of cars, such as weight and dimensions, to make sure they follow the rules. A failed check can mean disqualification."},{"id":"glossary-skid-block-plank","title":"Skid block (plank)","category":"Glossary","text":"Skid block (plank). The skid block, or plank, is a wooden strip under the car's floor, used to stop teams from running the car too low. If it is worn down more than allowed after the race, the car can be disqualified."},{"id":"glossary-telemetry","title":"Telemetry","category":"Glossary","text":"Telemetry. Telemetry is the live data stream from many sensors on the car, such as speeds, temperatures and tyre pressures, sent to the team's engineers so they can monitor and adjust the car during the session."},{"id":"glossary-track-evolution-rubbering-in","title":"Track evolution (rubbering in)","category":"Glossary","text":"Track evolution (rubbering in). Track evolution is the way a track gets faster as a session goes on, because cars lay down rubber and clear dust. It is why drivers usually go quicker at the end of a qualifying session."},{"id":"glossary-train-of-cars","title":"Train (of cars)","category":"Glossary","text":"Train (of cars). A train is a line of cars bunched up behind a slower car, usually because overtaking is difficult. Drivers in the middle of a train often suffer from dirty air and worn tyres."},{"id":"glossary-wheelspin","title":"Wheelspin","category":"Glossary","text":"Wheelspin. Wheelspin is when the driven wheels spin faster than the car's speed on acceleration, which wastes power and wears tyres. Drivers manage it with careful throttle control, especially out of slow corners."},{"id":"glossary-wind-tunnel-and-cfd","title":"Wind tunnel and CFD","category":"Glossary","text":"Wind tunnel and CFD. The wind tunnel and CFD, computational fluid dynamics, are the tools teams use to design and test the aerodynamics of the car. F1 rules limit how much each team may use them, to keep the playing field fairer."},{"id":"flags_and_signals-green-flag","title":"Green flag","category":"Flags and signals","text":"Green flag. A green flag means the track is clear and racing or normal running can resume. It is shown at the end of a yellow flag zone, and signals the hazard is behind you."},{"id":"flags_and_signals-yellow-flag-single","title":"Yellow flag (single)","category":"Flags and signals","text":"Yellow flag (single). A single waved yellow flag warns of danger on or beside the track in that sector, such as a stopped car or debris. Drivers must slow down and be ready to change direction, and overtaking is not allowed in the yellow zone until they pass the green flag."},{"id":"flags_and_signals-double-yellow-flag","title":"Double yellow flag","category":"Flags and signals","text":"Double yellow flag. Two waved yellow flags mean a serious hazard, such as a car blocking part of the track or marshals working on it. Drivers must slow down significantly and be prepared to stop if needed. No overtaking is allowed."},{"id":"flags_and_signals-yellow-flag-speed-rules-2026-guidelines","title":"Yellow flag speed rules (2026 guidelines)","category":"Flags and signals","text":"Yellow flag speed rules (2026 guidelines). The 2026 driving guidelines tell drivers they must show they slowed enough under yellow flags. A suggested benchmark is a sector time at least 5 percent slower under a single waved yellow, and at least 15 percent slower under double waved yellows. In qualifying, drivers are expected to abandon their lap if a yellow flag is waved in their sector. A car losing control under yellows is usually investigated."},{"id":"flags_and_signals-blue-flag","title":"Blue flag","category":"Flags and signals","text":"Blue flag. A blue flag tells a driver that a faster car is about to lap them and they must let it through at the next safe opportunity. It is used for lapped cars in a race. Ignoring blue flags repeatedly, commonly three times, can lead to a penalty."},{"id":"flags_and_signals-red-flag","title":"Red flag","category":"Flags and signals","text":"Red flag. A red flag means the session or race is stopped, because of a serious crash, debris, dangerous weather or anything making racing unsafe. Cars slow down and return to the pit lane. The pit exit is closed with a red light, and the cars queue there. Teams can repair cars and change tyres while stopped."},{"id":"flags_and_signals-black-flag","title":"Black flag","category":"Flags and signals","text":"Black flag. A black flag, shown with the driver's car number, means disqualification: the driver must return to the pits and is out of the session. It is rare and used for serious rule breaches or ignoring instructions."},{"id":"flags_and_signals-black-flag-with-orange-disc","title":"Black flag with orange disc","category":"Flags and signals","text":"Black flag with orange disc. A black flag with an orange circle, shown with the car number, tells a driver that their car has a mechanical problem that could be dangerous, such as loose bodywork or a fluid leak. They must pit so it can be fixed."},{"id":"flags_and_signals-black-and-white-flag-diagonal","title":"Black and white flag (diagonal)","category":"Flags and signals","text":"Black and white flag (diagonal). A black and white diagonal flag is a warning for unsportsmanlike driving, F1's version of a yellow card. It is shown with the driver's car number. It is also commonly used after repeated track limits breaches. Further offences can lead to a penalty."},{"id":"flags_and_signals-white-flag","title":"White flag","category":"Flags and signals","text":"White flag. A white flag warns that there is a slow-moving vehicle ahead on the track, such as a recovery vehicle, medical car or a car with a problem. It does not mean the last lap in Formula 1, even though some other racing series use it that way."},{"id":"flags_and_signals-yellow-and-red-striped-flag","title":"Yellow and red striped flag","category":"Flags and signals","text":"Yellow and red striped flag. A yellow flag with red vertical stripes warns of a slippery surface ahead, such as oil, water or loose gravel. It is held still, not waved. It does not require slowing down like the yellow flag, but drivers should be careful."},{"id":"flags_and_signals-chequered-flag","title":"Chequered flag","category":"Flags and signals","text":"Chequered flag. The black and white chequered flag signals the end of the session or race. It is waved at the finish line as each car completes its final lap. After the flag, drivers do a cool-down lap and return to the pits."},{"id":"flags_and_signals-flag-lights-and-panels","title":"Flag lights and panels","category":"Flags and signals","text":"Flag lights and panels. Marshal posts around the circuit have light panels that show the same signals as flags, and the steering wheel on every car also shows warnings. The electronic lights and physical flags mean exactly the same thing, and both are used at every grand prix."},{"id":"flags_and_signals-race-start-lights","title":"Race start lights","category":"Flags and signals","text":"Race start lights. Five red lights come on one by one above the grid. When all five go out, the race starts. A driver who moves before the lights go out has jumped the start and faces a penalty, usually a 10 second penalty."},{"id":"flags_and_signals-pit-exit-lights","title":"Pit exit lights","category":"Flags and signals","text":"Pit exit lights. At the end of the pit lane, a traffic light shows red when cars must not leave, such as during a red flag, a race start, or when a car is coming at speed on the track. Green means pit exit is open."},{"id":"flags_and_signals-safety-car-lights","title":"Safety Car lights","category":"Flags and signals","text":"Safety Car lights. The Safety Car has its orange lights on while it is deployed. If the lights turn green, lapped cars may overtake to rejoin the back of the queue. When the lights are switched off, it means the Safety Car will come into the pits at the end of that lap and racing restarts."},{"id":"race_weekend_and_points-the-2026-grid-at-a-glance","title":"The 2026 grid at a glance","category":"Race weekend and points","text":"The 2026 grid at a glance. The 2026 season has 11 teams with two drivers each, so 22 cars, and a calendar of 24 races. The teams are Alpine, Aston Martin, Audi, Cadillac, Ferrari, Haas, McLaren, Mercedes, Racing Bulls, Red Bull Racing and Williams. Cadillac is the new 11th team, and Audi has taken over what used to be the Sauber team."},{"id":"race_weekend_and_points-standard-race-weekend-schedule","title":"Standard race weekend schedule","category":"Race weekend and points","text":"Standard race weekend schedule. A normal grand prix weekend has three one-hour practice sessions (two on Friday, one on Saturday), then qualifying on Saturday, then the race on Sunday. Practice is for testing setups and tyres, qualifying sets the starting grid, and the race gives the points."},{"id":"race_weekend_and_points-free-practice-fp1-fp2-fp3","title":"Free practice (FP1, FP2, FP3)","category":"Race weekend and points","text":"Free practice (FP1, FP2, FP3). Free practice sessions are one hour each. Teams test car setups, try different tyre compounds, practise pit stops and run long stints to learn how the tyres wear. Lap times in practice do not matter much, since teams run with different fuel loads and engine settings, so do not read too much into who is fastest."},{"id":"race_weekend_and_points-qualifying-format-q1-q2-q3","title":"Qualifying format (Q1, Q2, Q3)","category":"Race weekend and points","text":"Qualifying format (Q1, Q2, Q3). Qualifying is a knockout session that sets the grid for the race. With 22 cars in 2026, Q1 lasts 18 minutes and the slowest six cars (17th to 22nd) are eliminated. Q2 lasts 15 minutes and the next six slowest (11th to 16th) are out. Q3 lasts 13 minutes, and the remaining 10 drivers fight for pole position and the top 10 grid spots. Each session starts fresh, with no lap times carried forward."},{"id":"race_weekend_and_points-why-qualifying-matters","title":"Why qualifying matters","category":"Race weekend and points","text":"Why qualifying matters. Overtaking is difficult at many circuits, so where you start strongly affects where you finish. That is why teams care so much about the single fastest lap in qualifying, and why pole position is valuable."},{"id":"race_weekend_and_points-sprint-weekend-format","title":"Sprint weekend format","category":"Race weekend and points","text":"Sprint weekend format. At six race weekends a season, F1 runs a sprint weekend. On Friday there is one practice session followed by Sprint Qualifying. On Saturday the Sprint race is held first, and then normal qualifying for the Sunday grand prix. Sunday is the full grand prix as usual. Sprint weekends have less practice time, so teams have less chance to learn the car."},{"id":"race_weekend_and_points-sprint-qualifying","title":"Sprint Qualifying","category":"Race weekend and points","text":"Sprint Qualifying. Sprint Qualifying is a shorter version of qualifying that sets the grid for the Sprint race only. It has three parts: SQ1 of 12 minutes, SQ2 of 10 minutes and SQ3 of 8 minutes. There are rules about which tyres must be used: medium tyres in SQ1 and SQ2, and soft tyres in SQ3."},{"id":"race_weekend_and_points-sprint-race","title":"Sprint race","category":"Race weekend and points","text":"Sprint race. The Sprint is a short race of about 100 km, roughly a third of a grand prix and around 30 minutes long. There is no mandatory pit stop, so most drivers run the whole race on one set of tyres. Only the top eight score points: 8 for the winner, then 7, 6, 5, 4, 3, 2 and 1."},{"id":"race_weekend_and_points-does-the-sprint-decide-the-sunday-grid","title":"Does the Sprint decide the Sunday grid?","category":"Race weekend and points","text":"Does the Sprint decide the Sunday grid?. No. The grid for Sunday's grand prix is set by normal qualifying on Saturday, separate from the Sprint result. Sprint points still count in the championship."},{"id":"race_weekend_and_points-race-distance-and-time-limit","title":"Race distance and time limit","category":"Race weekend and points","text":"Race distance and time limit. A grand prix is the smallest number of laps that go beyond 305 km. Monaco is shorter, at 260 km, because the track is slow and tight. A race has a maximum time of two hours, and if it is stopped with a red flag the total limit becomes three hours. Most races last around 1.5 to 2 hours."},{"id":"race_weekend_and_points-mandatory-tyre-rule","title":"Mandatory tyre rule","category":"Race weekend and points","text":"Mandatory tyre rule. In a dry grand prix, each driver must use at least two different dry tyre compounds, which means at least one pit stop. If it rains and wet or intermediate tyres are used, this requirement does not apply. In the Sprint there is no mandatory stop."},{"id":"race_weekend_and_points-how-the-race-starts","title":"How the race starts","category":"Race weekend and points","text":"How the race starts. Cars leave the pits for a formation lap, then line up in their grid slots. Five red lights come on one by one, and when they all go out the race starts. Starts are standing starts, with the cars stationary on the grid. A jump start is penalised."},{"id":"race_weekend_and_points-championship-points-for-a-grand-prix","title":"Championship points for a grand prix","category":"Race weekend and points","text":"Championship points for a grand prix. The top 10 finishers score points: 25 for first, 18 for second, 15 for third, 12 for fourth, 10 for fifth, 8 for sixth, 6 for seventh, 4 for eighth, 2 for ninth and 1 for tenth. There is no point for the fastest lap any more. If a race is stopped very early and cannot be restarted, a reduced points scale applies."},{"id":"race_weekend_and_points-drivers-versus-constructors-titles","title":"Drivers' versus Constructors' titles","category":"Race weekend and points","text":"Drivers' versus Constructors' titles. Two championships run at once. The Drivers' Championship adds up each driver's points. The Constructors' Championship adds the points of both drivers of each team. A driver can win the title even if their team does not win the constructors' one."},{"id":"race_weekend_and_points-when-the-race-ends","title":"When the race ends","category":"Race weekend and points","text":"When the race ends. The race ends when the leader takes the chequered flag after completing the full number of laps, or when the time limit is reached. Other cars finish when they cross the line after the leader. Drivers do a cool-down lap, park in the parc fermé area, and the top three go to the podium. Results can still change after the race if the stewards add penalties or cars fail technical checks."},{"id":"race_weekend_and_points-provisional-results","title":"Provisional results","category":"Race weekend and points","text":"Provisional results. Right after the race, the results are provisional. Time penalties given during or after the race are applied to the finishing times, which can change positions. The result becomes final after checks and any protest period."},{"id":"penalties_and_stewards-who-decides-penalties","title":"Who decides penalties","category":"Rules, penalties and stewards","text":"Who decides penalties. Incidents are judged by the stewards, a panel of officials including a former driver. They review video and data. The Race Director runs the session and may refer incidents to them. Fans often see the on-screen messages \"noted\", \"under investigation\", and then a decision."},{"id":"penalties_and_stewards-what-noted-and-under-investigation-mean","title":"What \"noted\" and \"under investigation\" mean","category":"Rules, penalties and stewards","text":"What \"noted\" and \"under investigation\" mean. \"Incident noted\" means the stewards have seen it and will look at it, but it has not been formally investigated yet. \"Under investigation\" means they are actively reviewing it and a penalty could follow. \"No further investigation\" or \"no further action\" means the incident is closed with no penalty. Decisions can take several laps, and some are made after the race."},{"id":"penalties_and_stewards-time-penalties-5-and-10-seconds","title":"Time penalties (5 and 10 seconds)","category":"Rules, penalties and stewards","text":"Time penalties (5 and 10 seconds). A time penalty adds seconds to a driver's race time. The most common are 5 and 10 seconds. If the driver makes a pit stop, the penalty is served in the pit box: the car stops for the length of the penalty before mechanics can work on it. If the driver does not pit again, the time is added to their finishing time after the race. These are the usual outcome for causing a collision or similar infringement."},{"id":"penalties_and_stewards-drive-through-penalty","title":"Drive-through penalty","category":"Rules, penalties and stewards","text":"Drive-through penalty. A drive-through is a penalty where the driver must go through the pit lane at the pit lane speed limit without stopping. It costs roughly 20 seconds or more, depending on the circuit. It is more serious than a 5 or 10 second time penalty."},{"id":"penalties_and_stewards-stop-go-penalty","title":"Stop-go penalty","category":"Rules, penalties and stewards","text":"Stop-go penalty. A stop-go penalty means the driver must enter the pit lane, stop in their own pit box for a set time (usually 10 seconds) with no work allowed, and then rejoin. It is a heavier penalty than a drive-through."},{"id":"penalties_and_stewards-serving-penalties-under-safety-car","title":"Serving penalties under Safety Car","category":"Rules, penalties and stewards","text":"Serving penalties under Safety Car. Drive-through and stop-go penalties generally cannot be served while a Safety Car or Virtual Safety Car is out. The driver has to serve them once racing resumes."},{"id":"penalties_and_stewards-grid-penalty","title":"Grid penalty","category":"Rules, penalties and stewards","text":"Grid penalty. A grid penalty moves a driver back some number of places on the starting grid. It is mostly given for technical reasons such as using more power unit components than allowed, or for a gearbox change, and sometimes for driving offences like causing a collision in an earlier race. If the penalty is larger than the number of cars ahead, the driver starts from the back."},{"id":"penalties_and_stewards-pit-lane-start","title":"Pit lane start","category":"Rules, penalties and stewards","text":"Pit lane start. A driver may be sent to start from the pit lane, behind the whole grid, for some breaches, such as changing a car's setup after qualifying outside the parc fermé rules. They leave the pits after the field passes."},{"id":"penalties_and_stewards-penalty-points-on-the-super-licence","title":"Penalty points on the super licence","category":"Rules, penalties and stewards","text":"Penalty points on the super licence. Dangerous or reckless driving can earn penalty points on a driver's super licence. Points stay for 12 months, and a driver who reaches 12 points gets a one-race ban. Under the 2026 guidelines, penalty points are meant for dangerous or reckless incidents, deliberate collisions and unsportsmanlike behaviour, so stewards are likely to hand out fewer of them than before."},{"id":"penalties_and_stewards-reprimand","title":"Reprimand","category":"Rules, penalties and stewards","text":"Reprimand. A reprimand is the lightest sanction: an official warning with no time loss. It goes on the driver's record."},{"id":"penalties_and_stewards-disqualification","title":"Disqualification","category":"Rules, penalties and stewards","text":"Disqualification. A driver can be disqualified from a session or the whole event, usually after a technical check finds the car breaks the rules, for example it is under the minimum weight or a part is the wrong size. A black flag during the race is how a disqualification is shown on track."},{"id":"penalties_and_stewards-causing-a-collision","title":"Causing a collision","category":"Rules, penalties and stewards","text":"Causing a collision. If a driver is judged to have caused a collision, the stewards usually give a time penalty, often 5 or 10 seconds depending on severity, and sometimes super licence points. A racing incident with no one at fault gets no penalty."},{"id":"penalties_and_stewards-track-limits","title":"Track limits","category":"Rules, penalties and stewards","text":"Track limits. Track limits are the white lines at the edge of the track. A driver must keep at least part of one tyre on or touching the white line. If all four wheels go fully beyond it, the driver has left the track. In qualifying, the lap time is usually deleted. In the race, drivers typically get warnings and then a penalty after repeated breaches. The 2026 guidelines let stewards delete a track limits breach if it came in a failed overtaking attempt with no clear advantage gained."},{"id":"penalties_and_stewards-gaining-a-lasting-advantage","title":"Gaining a lasting advantage","category":"Rules, penalties and stewards","text":"Gaining a lasting advantage. If a driver goes off track while overtaking and ends up in front, they are expected to give the place back. If they do not, they can be penalised. The key question is whether the driver gained a lasting advantage by leaving the track."},{"id":"penalties_and_stewards-defending-and-overtaking-rules","title":"Defending and overtaking rules","category":"Rules, penalties and stewards","text":"Defending and overtaking rules. A driver may defend their position but cannot make more than one move in reaction to an attacker, and must leave a car's width to the edge of the track. For an overtake, the attacker generally needs to be roughly alongside, with their front wheels about level with the other car's mirrors, by the apex to have a right to the corner. The 2026 guidelines say stewards look at the whole sequence of corners in a chicane or S-bend, not only a single corner."},{"id":"penalties_and_stewards-unsafe-release","title":"Unsafe release","category":"Rules, penalties and stewards","text":"Unsafe release. An unsafe release is when a team lets a car leave its pit box into the path of another car, or without all wheels secure. The team is penalised, commonly with a time penalty of 5 or 10 seconds, and the car may have to stop."},{"id":"penalties_and_stewards-pit-lane-speeding","title":"Pit lane speeding","category":"Rules, penalties and stewards","text":"Pit lane speeding. The pit lane has a speed limit, usually 80 km/h, and lower at some tracks. Exceeding it brings a penalty, which in races is commonly a time penalty, plus a fine in some cases."},{"id":"penalties_and_stewards-jump-start","title":"Jump start","category":"Rules, penalties and stewards","text":"Jump start. Sensors detect any car moving before the start lights go out. A jump start is usually punished with a 10 second penalty."},{"id":"penalties_and_stewards-impeding-in-qualifying","title":"Impeding in qualifying","category":"Rules, penalties and stewards","text":"Impeding in qualifying. In qualifying, a driver on a slow lap must not hinder another driver on a fast lap. If they do, they can get a penalty such as a grid drop or reprimand."},{"id":"penalties_and_stewards-right-of-review","title":"Right of review","category":"Rules, penalties and stewards","text":"Right of review. After a penalty, a team can ask the stewards to review the decision, but only if it brings significant new evidence that was not available at the time. It is not a simple appeal."},{"id":"penalties_and_stewards-power-unit-component-limits","title":"Power unit component limits","category":"Rules, penalties and stewards","text":"Power unit component limits. Each driver can only use a limited number of each power unit element per season. If they exceed the allowance, they get grid place penalties. This is why you sometimes see drivers start from the back after \"taking a new engine\" or new parts, even when they did not do anything wrong on track."},{"id":"penalties_and_stewards-parc-ferm-rules","title":"Parc fermé rules","category":"Rules, penalties and stewards","text":"Parc fermé rules. Parc fermé means cars are placed under restricted conditions. From the start of qualifying until the race, teams cannot change the car's setup freely; only limited work such as repairs or tyre changes is allowed. On sprint weekends teams can change the setup between the Sprint and grand prix qualifying. A breach can lead to a pit lane start."},{"id":"penalties_and_stewards-technical-checks-after-sessions","title":"Technical checks after sessions","category":"Rules, penalties and stewards","text":"Technical checks after sessions. After qualifying and the race, officials randomly check cars, including weight, floor and fuel. A failed check can mean disqualification. This is why results are provisional until all checks have been completed."},{"id":"race_control-safety-car-sc","title":"Safety Car (SC)","category":"Race control: Safety Car, VSC, red flags","text":"Safety Car (SC). The Safety Car is a real car that comes out onto the track after a serious incident, such as a crash or debris, to slow the whole field down while marshals work. All cars must line up behind it with a limited speed, and no overtaking is allowed. The gaps between cars are closed up, which can erase a big lead. Pit lanes stay open, so teams often pit then."},{"id":"race_control-why-teams-love-a-safety-car-pit-stop","title":"Why teams love a Safety Car pit stop","category":"Race control: Safety Car, VSC, red flags","text":"Why teams love a Safety Car pit stop. When the field is slowed under the Safety Car, a driver who pits loses much less time than during normal racing. This is sometimes called a \"cheap\" or \"free\" pit stop. It can transform strategy, so drivers who just pitted can be unlucky and those who pitted just after are lucky."},{"id":"race_control-safety-car-restart","title":"Safety Car restart","category":"Race control: Safety Car, VSC, red flags","text":"Safety Car restart. When the track is clear, the Safety Car comes into the pits at the end of a lap, its lights go out, and the race restarts. The leader controls the pace until the control line, then drivers can race flat out and overtake. Restarts often cause action because tyres are cold on the slow lap, and cars are bunched together."},{"id":"race_control-lapped-cars-and-the-safety-car","title":"Lapped cars and the Safety Car","category":"Race control: Safety Car, VSC, red flags","text":"Lapped cars and the Safety Car. When the Safety Car is out and the lights go green, lapped cars may overtake the cars between them and the leader, so they can rejoin at the back of the queue, which removes the lap they had lost. This is called unlapping."},{"id":"race_control-virtual-safety-car-vsc","title":"Virtual Safety Car (VSC)","category":"Race control: Safety Car, VSC, red flags","text":"Virtual Safety Car (VSC). The Virtual Safety Car is for smaller incidents, like a stopped car near the track, when a full Safety Car is not needed. There is no physical car. Every driver must slow down by roughly a third and stay above a target time shown on the steering wheel, called a delta. Overtaking is not allowed, and the gaps between cars stay roughly the same, so the race order is less disturbed than with a Safety Car."},{"id":"race_control-sc-and-vsc-how-they-differ","title":"SC and VSC: how they differ","category":"Race control: Safety Car, VSC, red flags","text":"SC and VSC: how they differ. A Safety Car bunches the field up behind a pace car and wipes out gaps. A Virtual Safety Car slows everyone down in place and keeps the gaps. The VSC is shown on TV as a \"VSC\" banner, and the Safety Car as \"SC\"."},{"id":"race_control-red-flag-stoppage","title":"Red flag stoppage","category":"Race control: Safety Car, VSC, red flags","text":"Red flag stoppage. A red flag stops the session or race completely. Cars go slowly back to the pit lane and queue at the pit exit. During a red flag teams may repair the car and change tyres, since no time is being lost on track. The race resumes with a restart, usually a standing start, after the track is cleared. The clock for the maximum race time continues up to its limit."},{"id":"race_control-why-there-are-red-flags","title":"Why there are red flags","category":"Race control: Safety Car, VSC, red flags","text":"Why there are red flags. Red flags happen after heavy crashes, when a car or debris is blocking the track, when barriers need repair, or when heavy rain makes conditions too dangerous. Red flags in qualifying freeze the session clock."},{"id":"race_control-race-suspension-and-delayed-start","title":"Race suspension and delayed start","category":"Race control: Safety Car, VSC, red flags","text":"Race suspension and delayed start. If rain or safety concerns delay a start, the race may begin behind the Safety Car. A race can also begin that way in heavy rain, with a standing or rolling restart later when the track is safer."},{"id":"race_control-race-director-and-race-control","title":"Race Director and race control","category":"Race control: Safety Car, VSC, red flags","text":"Race Director and race control. Race control is a room where officials run the event, using cameras, marshal reports and data. The Race Director decides when to deploy a Safety Car, VSC or red flag, and controls the start."},{"id":"race_control-pit-stops-and-pit-lane-basics","title":"Pit stops and pit lane basics","category":"Race control: Safety Car, VSC, red flags","text":"Pit stops and pit lane basics. In a pit stop, the car stops in its team's box and about twenty mechanics change all four wheels in a couple of seconds. Cars must follow the pit lane speed limit, and the team must release the driver safely. A normal stop costs a driver around 20 to 25 seconds in total from entering to leaving the pit lane, mostly in driving the pit lane at the limit."},{"id":"race_control-double-stack","title":"Double stack","category":"Race control: Safety Car, VSC, red flags","text":"Double stack. A double stack is when a team pits both of its drivers on consecutive laps, so the second car has to wait in the queue behind the first while the crew finishes. It can cost the second driver time, but teams use it under Safety Car conditions to save time overall."},{"id":"race_control-why-cars-cannot-refuel","title":"Why cars cannot refuel","category":"Race control: Safety Car, VSC, red flags","text":"Why cars cannot refuel. Refuelling during a race has been banned since 2010 for safety and cost reasons. Cars start with all the fuel they need for the race, so they get lighter as the race goes on, and lap times usually improve if tyres are good."},{"id":"tyres_and_strategy-who-supplies-the-tyres","title":"Who supplies the tyres","category":"Tyres and strategy","text":"Who supplies the tyres. Pirelli is the sole tyre supplier for Formula 1. All teams use the same tyres, so strategy comes from how and when each team uses them. The tyres are 18 inch."},{"id":"tyres_and_strategy-dry-tyre-colours","title":"Dry tyre colours","category":"Tyres and strategy","text":"Dry tyre colours. For dry weather, Pirelli has a range of slick compounds, from the hardest to the softest. For each race weekend it picks three of them and names them Hard, Medium and Soft. The sidewall marking shows the colours: white for Hard, yellow for Medium and red for Soft. On the TV graphics next to each driver you will see a coloured tyre icon with the number of laps it has done."},{"id":"tyres_and_strategy-soft-medium-and-hard-what-is-the-difference","title":"Soft, medium and hard: what is the difference","category":"Tyres and strategy","text":"Soft, medium and hard: what is the difference. Soft tyres give the most grip and the fastest lap time, but wear out the quickest. Hard tyres last longest but are slower, especially when new. Medium sits in between. Many races are decided by when a team chooses to switch between them."},{"id":"tyres_and_strategy-wet-weather-tyres","title":"Wet weather tyres","category":"Tyres and strategy","text":"Wet weather tyres. There are two wet tyres. Intermediates, marked with green, are for a damp or drying track. Full wets, marked with blue, are for heavy rain, and they can pump away large amounts of water. When it is raining, you often see drivers swap between intermediates and slicks as the track dries, and timing the change is a big strategic call."},{"id":"tyres_and_strategy-tyre-sets-and-allocation","title":"Tyre sets and allocation","category":"Tyres and strategy","text":"Tyre sets and allocation. Every driver gets a limited number of new tyre sets for the weekend, spread over soft, medium and hard. Teams must plan which sets to use in practice, qualifying and the race."},{"id":"tyres_and_strategy-what-is-a-pit-stop-strategy","title":"What is a pit stop strategy","category":"Tyres and strategy","text":"What is a pit stop strategy. A strategy is the plan for when to pit and which tyres to use. A one-stop strategy means pitting once, a two-stop means pitting twice. Teams choose based on tyre wear, track position and the risk of a Safety Car, and change the plan during the race as things develop."},{"id":"tyres_and_strategy-one-stop-versus-two-stop","title":"One-stop versus two-stop","category":"Tyres and strategy","text":"One-stop versus two-stop. A one-stop saves time in the pits and avoids traffic, but puts more wear on each tyre. A two-stop costs about 20 extra seconds in the pits but allows the driver to push harder on fresher tyres. Which is faster depends on how fast the tyres degrade at that circuit."},{"id":"tyres_and_strategy-track-position","title":"Track position","category":"Tyres and strategy","text":"Track position. Track position means where a car runs on the road. At circuits where overtaking is hard, being ahead on track is worth more than having better tyres, because a faster car can get stuck in dirty air behind a slower one."},{"id":"tyres_and_strategy-dirty-air-and-following-another-car","title":"Dirty air and following another car","category":"Tyres and strategy","text":"Dirty air and following another car. When a car follows closely, it drives in the turbulent air the car in front leaves behind. This cuts downforce and can overheat the tyres and brakes. It makes it harder to follow through corners and is a main reason overtaking is so hard. The 2026 cars have been designed to reduce this effect."},{"id":"tyres_and_strategy-the-undercut-in-practice","title":"The undercut in practice","category":"Tyres and strategy","text":"The undercut in practice. Pitting before a rival gives a driver fresh, grippy tyres, which can allow a quick out-lap while the rival is still on old tyres. When the rival pits the next lap, the undercutter can come out ahead. The undercut works best at tracks where tyres wear fast and where there is open track to rejoin into."},{"id":"tyres_and_strategy-the-overcut-in-practice","title":"The overcut in practice","category":"Tyres and strategy","text":"The overcut in practice. The overcut works when staying out longer is faster, for example when the track is clear and fresh tyres take time to warm up. The driver who stays out stays in clean air, sets quick laps, and then pits and rejoins ahead."},{"id":"tyres_and_strategy-offset-strategy","title":"Offset strategy","category":"Tyres and strategy","text":"Offset strategy. An offset strategy is when two drivers, or two rivals, are on different tyre choices or pit at different moments, so they are on different tyre ages. Later in the race, the driver on fresher tyres may be able to catch and pass those on older ones."},{"id":"tyres_and_strategy-tyre-management","title":"Tyre management","category":"Tyres and strategy","text":"Tyre management. Tyre management means driving smoothly, avoiding wheelspin and lock-ups, and sometimes going slightly slower so the tyres last longer. When you hear an engineer say \"manage the tyres\" or \"look after the rears\", this is what they mean."},{"id":"tyres_and_strategy-why-cars-do-not-all-pit-at-once","title":"Why cars do not all pit at once","category":"Tyres and strategy","text":"Why cars do not all pit at once. Teams pit at different laps to avoid queues, to react to rivals, and to take advantage of gaps in traffic. A pit stop at the wrong time can drop a driver behind slower cars, which loses more time than the stop itself."},{"id":"tyres_and_strategy-safety-car-strategy-gamble","title":"Safety Car strategy gamble","category":"Tyres and strategy","text":"Safety Car strategy gamble. If a Safety Car comes out, teams that have not yet pitted can swap tyres cheaply, so strategists watch for chances. Sometimes a team will gamble by staying out on old tyres to keep track position."},{"id":"cars_and_2026_rules-what-changed-in-2026","title":"What changed in 2026","category":"The 2026 cars and rules","text":"What changed in 2026. 2026 is the biggest rules reset in years. The cars are smaller and lighter, the power unit has a far bigger electric part, and the Drag Reduction System (DRS) is gone, replaced by active aerodynamics and a new Overtake Mode. A new team, Cadillac, joined, and new engine makers Audi and the Red Bull-Ford partnership arrived. Be aware that many older videos and articles describe the pre-2026 rules."},{"id":"cars_and_2026_rules-is-drs-still-used-in-2026","title":"Is DRS still used in 2026","category":"The 2026 cars and rules","text":"Is DRS still used in 2026. No. DRS, the rear-wing flap used to help overtaking, has been removed for 2026. Overtaking help now comes from active aerodynamics, which every driver can use in set zones, and from Overtake Mode, which gives extra electrical power to a car that is close enough behind another car."},{"id":"cars_and_2026_rules-the-2026-power-unit","title":"The 2026 power unit","category":"The 2026 cars and rules","text":"The 2026 power unit. The power unit is still a 1.6 litre V6 turbo petrol engine plus a hybrid system, but the electrical side is about three times more powerful than before. The MGU-K now delivers up to 350 kW, and the output is split roughly equally between the combustion engine and the electric motor. The MGU-H, which recovered energy from exhaust heat, has been removed to simplify the unit."},{"id":"cars_and_2026_rules-sustainable-fuel","title":"Sustainable fuel","category":"The 2026 cars and rules","text":"Sustainable fuel. In 2026 all cars run on 100 percent advanced sustainable fuel, which is made from non-fossil sources such as waste or captured carbon. This is part of F1's goal of net zero carbon by 2030."},{"id":"cars_and_2026_rules-active-aerodynamics","title":"Active aerodynamics","category":"The 2026 cars and rules","text":"Active aerodynamics. The front and rear wings now have movable parts that change position during a lap. In Corner Mode, the flaps are closed to give maximum downforce and grip through the corners. In Straight Mode, the flaps open to reduce drag, and increase top speed on a straight. Before the season these were called Z-mode and X-mode. Drivers open the wings on the straight sections of a lap (called zones), and they close again when the driver brakes or lifts off the throttle."},{"id":"cars_and_2026_rules-straight-mode-and-corner-mode","title":"Straight Mode and Corner Mode","category":"The 2026 cars and rules","text":"Straight Mode and Corner Mode. Corner Mode is the normal, high-downforce state of the wings, good for corners. Straight Mode is the low-drag state used in designated straight-line zones. Unlike DRS, any driver can use Straight Mode in the zones, with no need to be close to another car."},{"id":"cars_and_2026_rules-overtake-mode","title":"Overtake Mode","category":"The 2026 cars and rules","text":"Overtake Mode. Overtake Mode is the new overtaking aid for 2026. If a driver is within one second of the car ahead at the single detection point on the lap, which is usually the last corner, they get Overtake Mode on the following lap. It gives them extra electric energy (an extra 0.5 megajoules of recharge) and a stronger power delivery for longer, so they can attack. It can be used anywhere on the track, all at once or spread across a lap, which is different from DRS, which only worked in set zones."},{"id":"cars_and_2026_rules-boost-mode","title":"Boost Mode","category":"The 2026 cars and rules","text":"Boost Mode. Boost is a button the driver can press at any time to deploy the maximum electrical power, for attack or defence. It uses stored battery energy, so using it too often can leave a car short of power later in the lap."},{"id":"cars_and_2026_rules-recharge-and-super-clipping","title":"Recharge and super clipping","category":"The 2026 cars and rules","text":"Recharge and super clipping. Because the battery is so important, cars constantly harvest energy. They do it under braking, at part throttle, by lifting early before corners (lift and coast), and by a technique called super clipping, where the car recovers energy at the end of a long straight while the driver is still at full throttle. This can make a car look like it is slowing slightly at the end of a straight, which is normal and not a fault."},{"id":"cars_and_2026_rules-why-cars-seem-to-slow-at-the-end-of-straights","title":"Why cars seem to slow at the end of straights","category":"The 2026 cars and rules","text":"Why cars seem to slow at the end of straights. In 2026 the combustion engine and battery share the work, so at the end of long straights the car may stop accelerating as hard while it recharges. Viewers sometimes mistake this for a problem. It is a deliberate energy-management choice, sometimes called super clipping."},{"id":"cars_and_2026_rules-lighter-and-smaller-cars","title":"Lighter and smaller cars","category":"The 2026 cars and rules","text":"Lighter and smaller cars. The 2026 cars are smaller and lighter than the 2022 to 2025 generation, which makes them more agile in corners. The beam wing at the rear has been removed and the wings are narrower, with cleaner endplates. They also produce less dirty air, which should help cars follow each other more closely."},{"id":"cars_and_2026_rules-who-builds-the-engines-in-2026","title":"Who builds the engines in 2026","category":"The 2026 cars and rules","text":"Who builds the engines in 2026. Mercedes supplies Mercedes, McLaren, Williams and Alpine. Ferrari supplies Ferrari, Haas and Cadillac. Honda supplies Aston Martin. Audi builds its own power unit for its works team. Red Bull Powertrains, working with Ford, supplies Red Bull Racing and Racing Bulls."},{"id":"cars_and_2026_rules-what-is-a-works-team-versus-a-customer-team","title":"What is a works team versus a customer team","category":"The 2026 cars and rules","text":"What is a works team versus a customer team. A works team builds its own engine, such as Ferrari or Mercedes. A customer team buys engines from another manufacturer, such as Haas buying from Ferrari. Some teams, like Aston Martin with Honda, have a close partnership with one supplier."},{"id":"cars_and_2026_rules-cadillac-the-11th-team","title":"Cadillac, the 11th team","category":"The 2026 cars and rules","text":"Cadillac, the 11th team. Cadillac joined the grid in 2026 as the eleventh team, which brought the field to 22 cars. It uses Ferrari engines to start with, and plans to build its own power unit later in the decade."},{"id":"cars_and_2026_rules-qualifying-with-22-cars","title":"Qualifying with 22 cars","category":"The 2026 cars and rules","text":"Qualifying with 22 cars. Because there are now 22 cars, the bottom six cars are eliminated in each of Q1 and Q2, instead of the bottom five when there were 20 cars. Q3 still has the top 10."},{"id":"cars_and_2026_rules-car-names-like-w17","title":"Car names like W17","category":"The 2026 cars and rules","text":"Car names like W17. Each team gives its car a model name that changes every year. For example, the 2026 Mercedes is called the W17. The name has no effect on how it races, but you will see it on screen and in commentary."},{"id":"reading_the_broadcast-the-timing-tower","title":"The timing tower","category":"Reading the live broadcast","text":"The timing tower. The timing tower is the list on the side of the screen showing each driver in race order. Each line normally shows the position, a three-letter driver code, the team colour, the tyre type the driver is using, and the time gap. It updates all the time, so watch it to see who is gaining or losing places."},{"id":"reading_the_broadcast-three-letter-driver-codes","title":"Three-letter driver codes","category":"Reading the live broadcast","text":"Three-letter driver codes. Drivers are shown with three-letter abbreviations, usually the first three letters of their surname, such as VER for Verstappen. A few are different, so check the full name when a broadcast first shows it."},{"id":"reading_the_broadcast-gap-to-leader-versus-interval","title":"Gap to leader versus interval","category":"Reading the live broadcast","text":"Gap to leader versus interval. Some graphics show the gap to the race leader, others show the interval to the car just ahead. If you see a small interval like +0.8, that car is very close to the one in front. In 2026 an interval below one second at the detection point lets a driver use Overtake Mode on the next lap."},{"id":"reading_the_broadcast-tyre-icons-and-tyre-age","title":"Tyre icons and tyre age","category":"Reading the live broadcast","text":"Tyre icons and tyre age. Next to each driver you may see a coloured circle: red for Soft, yellow for Medium, white for Hard, green for Intermediate and blue for Wet. A number may show how many laps old that set of tyres is. Older tyres usually mean a pit stop is coming soon."},{"id":"reading_the_broadcast-pit-stop-count","title":"Pit stop count","category":"Reading the live broadcast","text":"Pit stop count. Some graphics show the number of pit stops a driver has made so far. A driver with fewer stops may be on a longer strategy and could pit later."},{"id":"reading_the_broadcast-purple-green-and-yellow-lap-times","title":"Purple, green and yellow lap times","category":"Reading the live broadcast","text":"Purple, green and yellow lap times. Purple means the fastest time anyone has set so far in the session. Green is a personal best for that driver. Yellow means slower than their best. Sector times appear in the same colours, so a \"purple sector\" means the fastest anyone has gone in that part of the track."},{"id":"reading_the_broadcast-fastest-lap-graphic","title":"Fastest lap graphic","category":"Reading the live broadcast","text":"Fastest lap graphic. When a driver sets the fastest lap of the race, the graphic shows purple. In the race, it does not earn a point any more, but it is still a nice stat, and often a sign that a driver on fresh tyres is pushing hard."},{"id":"reading_the_broadcast-what-pit-out-and-dnf-mean-on-screen","title":"What PIT, OUT and DNF mean on screen","category":"Reading the live broadcast","text":"What PIT, OUT and DNF mean on screen. PIT means a driver is in the pit lane, and OUT usually means retired or out of the session. Some graphics also show DNF or a red cross for retirement."},{"id":"reading_the_broadcast-on-screen-flags-and-banners","title":"On-screen flags and banners","category":"Reading the live broadcast","text":"On-screen flags and banners. When a flag or control message appears on screen, like yellow, SC or VSC, it matches the situations described in the flags guide. A yellow banner often shows the sector. SC means Safety Car, VSC means Virtual Safety Car, and a red banner means the race has been stopped."},{"id":"reading_the_broadcast-team-radio","title":"Team radio","category":"Reading the live broadcast","text":"Team radio. Team radio messages are short conversations between the driver and the pit wall. Terms you will hear include \"box, box\" (pit now), \"push\" (drive faster), \"manage\" (save tyres or energy), \"lift and coast\" (lift early before braking to save energy or fuel), and \"stay out\" (do not pit yet)."},{"id":"reading_the_broadcast-what-a-gap-closing-really-means","title":"What a gap closing really means","category":"Reading the live broadcast","text":"What a gap closing really means. If the gap to the car ahead is dropping by a few tenths each lap, the driver behind is faster, which usually leads to an attack in a few laps. In traffic or dirty air, though, a faster car can still struggle to pass."},{"id":"reading_the_broadcast-why-a-driver-slows-on-the-straight","title":"Why a driver slows on the straight","category":"Reading the live broadcast","text":"Why a driver slows on the straight. If a car looks slow or you see a car move off the racing line, it may be because of a yellow flag, a Safety Car, or a driver managing energy or tyres. Look for a banner on screen or listen to the commentators."},{"id":"reading_the_broadcast-battles-and-defence","title":"Battles and defence","category":"Reading the live broadcast","text":"Battles and defence. A driver who is being chased may defend by taking the inside line into a corner, but must leave space and can only move once in reaction to the attacker. Commentators describe attacks with phrases like \"getting a run\" or \"using the tow\", meaning the car behind is getting a speed advantage from the slipstream."},{"id":"reading_the_broadcast-weather-and-the-radar","title":"Weather and the radar","category":"Reading the live broadcast","text":"Weather and the radar. If it rains, the TV graphics may show a rain radar and the track status. Teams look at the radar to decide whether to switch to Intermediate tyres, which is one of the biggest strategy calls in a race."}];

const prep = $('Prepare').first().json;
const queries = $('Parse sub-queries').all().map(i => i.json.q);

// ---- tiny text normaliser: lower-case, strip accents (fermé -> ferme), UK/US spelling, light stemming
const SYN = { tire: 'tyre', tires: 'tyres', curb: 'kerb', curbs: 'kerbs', color: 'colour', colors: 'colours', quali: 'qualifying' };
const STOP = new Set(('a an the is are was were be been being of to in on at for from by with and or but if then than that this these those ' +
  'it its as do does did what whats why how when who which can could should would will may might i you he she we they me my your our their ' +
  'there here so not no yes about into over under up down out off just also very more most some any tell mean means ' +
  'work works happen happens get gets').split(' '));
function stem(t) {
  if (t.length > 4 && t.endsWith('ies')) t = t.slice(0, -3) + 'y';
  else if (t.length > 3 && t.endsWith('s') && !t.endsWith('ss')) t = t.slice(0, -1);
  if (t.length > 5 && t.endsWith('ing')) t = t.slice(0, -3);
  if (t.length > 4 && t.endsWith('e')) t = t.slice(0, -1);
  return t;
}
function tokens(s) {
  return (String(s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').match(/[a-z0-9]+/g) || [])
    .map(t => SYN[t] || t).filter(t => !STOP.has(t)).map(stem);
}

// ---- BM25 index over the knowledge base (title counted 3x so exact terms win)
const docs = KB.map(d => {
  const toks = tokens((d.title + ' ').repeat(3) + d.text);
  const tf = new Map();
  toks.forEach(t => tf.set(t, (tf.get(t) || 0) + 1));
  return { id: d.id, tf, len: toks.length };
});
const N = docs.length;
const avgdl = docs.reduce((a, d) => a + d.len, 0) / N;
const df = new Map();
docs.forEach(d => d.tf.forEach((_, t) => df.set(t, (df.get(t) || 0) + 1)));
const K1 = 1.5, B = 0.75;
function bm25(queryTokens) {
  const out = new Map();
  for (const d of docs) {
    let s = 0;
    for (const t of new Set(queryTokens)) {
      const f = d.tf.get(t);
      if (!f) continue;
      const idf = Math.log(1 + (N - df.get(t) + 0.5) / (df.get(t) + 0.5));
      s += idf * (f * (K1 + 1)) / (f + K1 * (1 - B + B * d.len / avgdl));
    }
    if (s > 0) out.set(d.id, s);
  }
  return out;
}

// ---- 1) BM25 for every query, keep the best score per chunk
const lexical = new Map();
for (const q of queries) {
  for (const [id, s] of bm25(tokens(q))) lexical.set(id, Math.max(lexical.get(id) || 0, s));
}
const lexicalRanked = [...lexical.entries()].sort((a, b) => b[1] - a[1]).slice(0, 8).map(e => e[0]);

// ---- 2) dense hits from the vector store node (one item per hit, all sub-queries pooled)
const byId = new Map(KB.map(d => [d.id, d]));
const dense = new Map();
let order = 0;
for (const it of $input.all()) {
  const j = it.json || {};
  const doc = j.document || j;
  const id = doc.metadata && doc.metadata.id;
  if (!id || !byId.has(id)) continue;                       // empty item or unknown chunk
  const score = typeof j.score === 'number' ? j.score : (typeof doc.score === 'number' ? doc.score : 0);
  const prev = dense.get(id);
  if (!prev || score > prev.score) dense.set(id, { score, order: prev ? prev.order : order++ });
}
const denseRanked = [...dense.entries()]
  .sort((a, b) => (b[1].score - a[1].score) || (a[1].order - b[1].order))
  .map(e => e[0]);

// ---- 3) Reciprocal Rank Fusion: 1/(60 + rank) from each list, summed
const RRF_K = 60;
const fused = new Map();
const addRanks = list => list.forEach((id, i) => fused.set(id, (fused.get(id) || 0) + 1 / (RRF_K + i + 1)));
addRanks(denseRanked);
addRanks(lexicalRanked);
const top = [...fused.entries()].sort((a, b) => b[1] - a[1]).slice(0, 5);

const retrieved = top.map(([id, rrf]) => {
  const d = byId.get(id);
  return {
    id, title: d.title, category: d.category, text: d.text,
    rrf: Number(rrf.toFixed(4)),
    dense: dense.has(id) ? Number(dense.get(id).score.toFixed(3)) : null,
    bm25: lexical.has(id) ? Number(lexical.get(id).toFixed(2)) : null,
  };
});
const contextText = retrieved.length
  ? retrieved.map((r, i) => '[' + (i + 1) + '] ' + r.title + ' (' + r.category + ')\n' + r.text).join('\n\n')
  : '(no matching notes were found)';

return [{ json: {
  queries,
  contextText,
  retrieved,
  debug: { denseCandidates: denseRanked.length, lexicalCandidates: lexicalRanked.length },
} }];

